check_code:
A,B=70,50; C=180-A-B
corr={'P':'A','Q':'B','R':'C'}
side={frozenset('AB'):6}; ang={'A':A,'B':B,'C':C}
def side_ok(s): return side.get(frozenset(corr[c] for c in s))==6
def ang_ok(v,val): return ang[corr[v]]==val
opts={'A':('QR','R'),'B':('QR','Q'),'C':('QP','P'),'D':('QP','R')}
ok=[k for k,(s,v) in opts.items() if side_ok(s) and ang_ok(v,60)]
assert ok==['D']
